    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,28,'Rule 1 given by the headmaster (choose one of the three correct letters).','[{"letter":"A","text":"Make sure they tidy up the hall and rooms after the conference."},{"text":"Provide cleaners for the conference.","letter":"B"},{"text":"Provide lunch for the speakers","letter":"C"},{"letter":"D","text":"Make a record of what each student at the conference wants to study at University."},{"text":"Make a record of what each student at the conference is studying now.","letter":"E"},{"text":"Make a record of all students who attend the conference.","letter":"F"},{"letter":"G","text":"Help organise the travel arrangements for the speakers."}]'::jsonb,'"F"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,29,'Rule 2 given by the headmaster (choose one of the three correct letters).','[{"letter":"A","text":"Make sure they tidy up the hall and rooms after the conference."},{"letter":"B","text":"Provide cleaners for the conference."},{"letter":"C","text":"Provide lunch for the speakers"},{"letter":"D","text":"Make a record of what each student at the conference wants to study at University."},{"text":"Make a record of what each student at the conference is studying now.","letter":"E"},{"text":"Make a record of all students who attend the conference.","letter":"F"},{"text":"Help organise the travel arrangements for the speakers.","letter":"G"}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,30,'Rule 3 given by the headmaster (choose one of the three correct letters).','[{"text":"Make sure they tidy up the hall and rooms after the conference.","letter":"A"},{"text":"Provide cleaners for the conference.","letter":"B"},{"text":"Provide lunch for the speakers","letter":"C"},{"letter":"D","text":"Make a record of what each student at the conference wants to study at University."},{"text":"Make a record of what each student at the conference is studying now.","letter":"E"},{"letter":"F","text":"Make a record of all students who attend the conference."},{"text":"Help organise the travel arrangements for the speakers.","letter":"G"}]'::jsonb,'"G"'::jsonb);
